// Unit tests for `get_config_schema`: the tool returns the schema file that is on disk, not a
// retyped copy — the built schema is generated by `npm run schema:build`, so the assertions read
// the file directly and compare. Versioned fields (`$schema`, the v0 in `$id`) are asserted, not
// a hash. Reads no site, touches no network.

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

import { GET_CONFIG_SCHEMA_DESCRIPTION, GET_CONFIG_SCHEMA_NAME, getConfigSchema } from "../src/get-config-schema.js";

// The same file the tool reads, reached from this test (`<pkg>/dist/tests`), the way the other
// spec-reading tests do.
const SCHEMA_PATH = fileURLToPath(new URL("../../../../spec/config/v0.schema.json", import.meta.url));

interface BuiltSchema {
  $schema: string;
  $id: string;
  title: string;
  type: string;
  properties: Record<string, unknown>;
}

test("the tool name and description are stable and say what comes back", () => {
  assert.equal(GET_CONFIG_SCHEMA_NAME, "get_config_schema");
  assert.match(GET_CONFIG_SCHEMA_DESCRIPTION, /spec\/config\/v0\.schema\.json/);
  assert.match(GET_CONFIG_SCHEMA_DESCRIPTION, /nothing is fetched/i);
});

test("get_config_schema returns the schema file on disk byte for byte", () => {
  assert.equal(getConfigSchema(), readFileSync(SCHEMA_PATH, "utf8"));
});

test("the returned schema is the versioned config contract it claims to be", () => {
  const schema = JSON.parse(getConfigSchema()) as BuiltSchema;
  assert.equal(schema.$schema, "https://json-schema.org/draft/2020-12/schema");
  assert.match(schema.$id, /\/spec\/config\/v0\.schema\.json$/);
  assert.equal(schema.title, "Seaworthy config");
  assert.equal(schema.type, "object");
  // The options the config parser knows must be described by the same document.
  for (const key of ["root", "basePath", "failOn", "rendered", "network", "history", "checks", "ignore", "suppressions", "baseline"]) {
    assert.ok(key in schema.properties, `properties.${key} is missing from the built schema`);
  }
});
